input.new_string:
/**
 * Validators for one settings field, with no `.default()`.
 *
 * Zod 4 applies `.default()` even through `.partial()`, so a patch schema built
 * from the defaulted object would fill every omitted key (digest hour 7, no
 * two-factor, no flag overrides) and a partial save would clobber the row.
 */
const organizationSettingsFields = {
  defaultIssueStatus: z.enum([
    "backlog",
    "todo",
    "in_progress",
    "in_review",
    "done",
    "canceled",
  ]),
  allowPublicProjects: z.boolean(),
  requireTwoFactor: z.boolean(),
  digestHourUtc: z.number().int().min(0).max(23),
  enabledFlagOverrides: z.array(z.string()),
};

/** Complete settings document. Defaults apply only when every field is asked for. */
export const organizationSettingsSchema = z.object({
  defaultIssueStatus: organizationSettingsFields.defaultIssueStatus.default("backlog"),
  allowPublicProjects: organizationSettingsFields.allowPublicProjects.default(false),
  requireTwoFactor: organizationSettingsFields.requireTwoFactor.default(false),
  digestHourUtc: organizationSettingsFields.digestHourUtc.default(7),
  enabledFlagOverrides: organizationSettingsFields.enabledFlagOverrides.default(
    () => [],
  ),
});

/**
 * A settings patch: only keys the caller sent. `0`, `false`, and `[]` stay,
 * because they are real values; omitted keys are absent, not defaulted.
 */
export const organizationSettingsPatchSchema = z
  .object(organizationSettingsFields)
  .partial();

