import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { updateOrganizationSchema } from "@/schemas/organization";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as orgService from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("updateOrganization settings patch", () => {
  it("changes only the submitted settings, including falsy values, and isolates workspaces", async () => {
    const starter = await createTenant("starter-ws", "starter");
    const other = await createTenant("other-ws", "growth");

    await orgRepo.updateOrg(starter.org.id, {
      orgId: starter.org.id,
      settings: {
        defaultIssueStatus: "todo",
        allowPublicProjects: false,
        requireTwoFactor: true,
        digestHourUtc: 18,
        enabledFlagOverrides: ["digest_email", "activity_feed"],
      },
    });
    await orgRepo.updateOrg(other.org.id, {
      orgId: other.org.id,
      settings: {
        requireTwoFactor: true,
        digestHourUtc: 18,
        enabledFlagOverrides: ["csv_export"],
      },
    });

    const statusOnly = updateOrganizationSchema.parse({
      orgId: starter.org.id,
      settings: { defaultIssueStatus: "in_progress" },
    });
    const afterStatus = await orgService.updateOrganization(starter.actors.admin, statusOnly);
    expect(afterStatus.settings).toMatchObject({
      defaultIssueStatus: "in_progress",
      allowPublicProjects: false,
      requireTwoFactor: true,
      digestHourUtc: 18,
      enabledFlagOverrides: ["digest_email", "activity_feed"],
    });

    const publicOnly = updateOrganizationSchema.parse({
      orgId: other.org.id,
      settings: { allowPublicProjects: true },
    });
    const afterPublic = await orgService.updateOrganization(other.actors.admin, publicOnly);
    expect(afterPublic.settings).toMatchObject({
      allowPublicProjects: true,
      requireTwoFactor: true,
      digestHourUtc: 18,
      enabledFlagOverrides: ["csv_export"],
    });

    const falsy = updateOrganizationSchema.parse({
      orgId: starter.org.id,
      settings: {
        digestHourUtc: 0,
        requireTwoFactor: false,
        allowPublicProjects: false,
        enabledFlagOverrides: [],
      },
    });
    const afterFalsy = await orgService.updateOrganization(starter.actors.admin, falsy);
    expect(afterFalsy.settings).toMatchObject({
      defaultIssueStatus: "in_progress",
      allowPublicProjects: false,
      requireTwoFactor: false,
      digestHourUtc: 0,
      enabledFlagOverrides: [],
    });

    const renamed = await orgService.updateOrganization(starter.actors.admin, {
      orgId: starter.org.id,
      name: "Renamed Starter",
    });
    expect(renamed.name).toBe("Renamed Starter");
    expect(renamed.settings).toEqual(afterFalsy.settings);

    const otherStill = await orgRepo.findOrgById(other.org.id);
    expect(otherStill?.settings).toMatchObject({
      allowPublicProjects: true,
      requireTwoFactor: true,
      digestHourUtc: 18,
      enabledFlagOverrides: ["csv_export"],
    });
    expect(otherStill?.name).toBe(other.org.name);
  });

  it("rejects a digest hour outside 0-23 and does not write it", async () => {
    const tenant = await createTenant("bad-hour", "growth");
    await expect(
      orgService.updateOrganization(tenant.actors.admin, {
        orgId: tenant.org.id,
        settings: { digestHourUtc: 24 },
      }),
    ).rejects.toThrow();
    const stored = await orgRepo.findOrgById(tenant.org.id);
    expect(stored?.settings.digestHourUtc).toBe(tenant.org.settings.digestHourUtc);
  });
});

